/**
 * skill-ui-bridge OpenClaw Plugin v4.0
 *
 * 方案：监听 gateway_start hook，在 gateway 启动后把 manifest + bootstrap.js
 * 内联写入 control-ui 的 index.html。同时在 gateway_stop 时还原原始文件。
 *
 * 原因：control-ui 静态文件服务优先级高于插件 HTTP handler，
 * 无法在运行时拦截 GET /，因此在启动时直接修改静态文件是唯一的插件方案。
 */

import path from "node:path";
import fs from "node:fs";
import { createRequire } from "node:module";

const PLUGIN_ID = "skill-ui-bridge";
const MANIFEST_PATH = "/plugins/skill-ui/manifest";
const INLINE_MARKER = "/* skill-ui-bridge:inline */";

// ─── Plugin definition ────────────────────────────────────────────────────────

const plugin = {
  id: PLUGIN_ID,
  name: "Skill UI Bridge",
  description: "Injects skill-ui HTML renderer into control-ui at gateway startup",

  register(api) {
    const bootstrapSrc = resolveBootstrapSrc();
    const skillsDir = resolveSkillsDir(api);

    if (!bootstrapSrc) {
      api.logger.warn(`${PLUGIN_ID}: cannot find skill-ui-bridge.js source, aborting`);
      return;
    }

    // gateway_start: 注入 index.html
    api.on("gateway_start", async () => {
      try {
        await injectIndexHtml({ bootstrapSrc, skillsDir, logger: api.logger });
      } catch (err) {
        api.logger.warn(`${PLUGIN_ID}: inject failed: ${err?.message}`);
      }
    });

    // gateway_stop: 还原 index.html
    api.on("gateway_stop", async () => {
      try {
        restoreIndexHtml(api.logger);
      } catch (err) {
        api.logger.warn(`${PLUGIN_ID}: restore failed: ${err?.message}`);
      }
    });

    // 同时注册 manifest HTTP 路由（需要鉴权，供调试用）
    const handler = createManifestHandler({ skillsDir, logger: api.logger });
    if (typeof api.registerHttpRoute === 'function') {
      api.registerHttpRoute({ path: '/plugins/skill-ui/manifest', handler });
    } else if (typeof api.registerHttpHandler === 'function') {
      api.registerHttpHandler(handler);
    }

    api.logger.info(`${PLUGIN_ID}: registered (gateway_start hook will inject index.html)`);
  },
};

export default plugin;

// ─── 注入 / 还原 ──────────────────────────────────────────────────────────────

const STATIC_JS_NAME = "skill-ui-init.js";

async function injectIndexHtml({ bootstrapSrc, skillsDir, logger }) {
  const indexPath = resolveIndexHtmlPath();
  if (!indexPath) {
    logger.warn(`${PLUGIN_ID}: cannot find control-ui index.html`);
    return;
  }

  const staticDir = path.dirname(indexPath);
  const staticJsPath = path.join(staticDir, STATIC_JS_NAME);

  // 1. 把 manifest + bootstrap 合并写成同源静态 JS（CSP script-src 'self' 允许同源文件）
  const manifest = buildManifest(skillsDir, logger);
  const bootstrapJs = fs.readFileSync(bootstrapSrc, "utf-8");
  const bootstrapPatched = patchBootstrap(bootstrapJs);

  const initJs = [
    `// skill-ui-bridge auto-generated`,
    `window.__skillUiManifest = ${JSON.stringify(manifest)};`,
    ``,
    bootstrapPatched,
  ].join("\n");

  fs.writeFileSync(staticJsPath, initJs, "utf-8");
  logger.info(`${PLUGIN_ID}: wrote ${staticJsPath} (${initJs.length} chars)`);

  // 2. index.html 用 <script src> 加载同源文件（CSP 允许）
  let html = fs.readFileSync(indexPath, "utf-8");
  html = cleanInjection(html);

  const scriptTag = `<script src="./${STATIC_JS_NAME}"></script>`;
  html = html.replace("</head>", `${scriptTag}\n</head>`);

  const backupPath = indexPath + ".orig";
  if (!fs.existsSync(backupPath)) {
    fs.writeFileSync(backupPath, fs.readFileSync(indexPath, "utf-8"), "utf-8");
  }

  fs.writeFileSync(indexPath, html, "utf-8");
  logger.info(`${PLUGIN_ID}: injected index.html with <script src="./${STATIC_JS_NAME}">`);
}

function restoreIndexHtml(logger) {
  const indexPath = resolveIndexHtmlPath();
  if (!indexPath) return;
  const backupPath = indexPath + ".orig";
  if (fs.existsSync(backupPath)) {
    fs.copyFileSync(backupPath, indexPath);
    logger.info(`${PLUGIN_ID}: restored original index.html`);
  }
  const staticJsPath = path.join(path.dirname(indexPath), STATIC_JS_NAME);
  if (fs.existsSync(staticJsPath)) {
    fs.unlinkSync(staticJsPath);
    logger.info(`${PLUGIN_ID}: removed ${STATIC_JS_NAME}`);
  }
}

function cleanInjection(html) {
  html = html.replace(/<script>\nwindow\.__skillUiManifest[\s\S]*?<\/script>\n?/g, "");
  html = html.replace(/<script>\/\* skill-ui-bridge:inline \*\/[\s\S]*?<\/script>\n?/g, "");
  html = html.replace(/<script src="\/plugins\/skill-ui\/bootstrap\.js"><\/script>\n?/g, "");
  html = html.replace(/<script src="\.\/skill-ui-init\.js"><\/script>\n?/g, "");
  return html;
}

function patchBootstrap(js) {
  // skill-ui-bridge.js v2+ 已经原生支持 window.__skillUiManifest，无需 patch
  // 保留此函数以兼容旧版本：检查是否已包含 __skillUiManifest 分支
  if (js.includes('window.__skillUiManifest')) return js;

  // 旧版本 patch：在 boot() 开头优先读 window.__skillUiManifest
  const original = `async function boot() {
    try {
      var authHeader = getAuthHeader();
      var fetchOpts = authHeader ? { headers: { 'Authorization': authHeader } } : {};
      var r = await fetch('/plugins/skill-ui/manifest', fetchOpts);
      if (!r.ok) { console.warn('[skill-ui-bridge] manifest', r.status); return; }
      var m = await r.json();`;

  const patched = `async function boot() {
    try {
      var m;
      if (window.__skillUiManifest) {
        m = window.__skillUiManifest;
      } else {
        var authHeader = getAuthHeader();
        var fetchOpts = authHeader ? { headers: { 'Authorization': authHeader } } : {};
        var r = await fetch('/plugins/skill-ui/manifest', fetchOpts);
        if (!r.ok) { console.warn('[skill-ui-bridge] manifest', r.status); return; }
        m = await r.json();
      }`;

  if (js.includes(original)) return js.replace(original, patched);
  return js;
}

// ─── Manifest builder ─────────────────────────────────────────────────────────

function buildManifest(skillsDir, logger) {
  const manifest = { skills: [], timestamp: Date.now() };
  if (!skillsDir || !fs.existsSync(skillsDir)) return manifest;
  try {
    const entries = fs.readdirSync(skillsDir, { withFileTypes: true });
    for (const entry of entries) {
      if (!entry.isDirectory()) continue;
      if (entry.name.startsWith(".") || entry.name.includes("..")) continue;
      const configPath = path.join(skillsDir, entry.name, "ui-config.json");
      if (!fs.existsSync(configPath)) continue;
      try {
        const config = JSON.parse(fs.readFileSync(configPath, "utf8"));
        manifest.skills.push({ name: entry.name, config });
      } catch (err) {
        logger?.warn(`${PLUGIN_ID}: bad ui-config.json in '${entry.name}': ${err?.message}`);
      }
    }
  } catch (err) {
    logger?.warn(`${PLUGIN_ID}: cannot read skillsDir: ${err?.message}`);
  }
  return manifest;
}

// ─── Manifest HTTP handler（调试用）──────────────────────────────────────────

function createManifestHandler({ skillsDir, logger }) {
  return async (req, res) => {
    const pathname = new URL(req.url ?? "/", "http://localhost").pathname;
    if (pathname !== MANIFEST_PATH) return false;
    if (req.method === "OPTIONS") {
      res.writeHead(204, CORS_HEADERS);
      res.end();
      return true;
    }
    const manifest = buildManifest(skillsDir, logger);
    const body = JSON.stringify(manifest);
    res.writeHead(200, {
      "Content-Type": "application/json; charset=utf-8",
      "Content-Length": Buffer.byteLength(body),
      ...CORS_HEADERS,
    });
    res.end(body);
    return true;
  };
}

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

// ─── 路径解析 ─────────────────────────────────────────────────────────────────

function resolveBootstrapSrc() {
  try {
    const selfUrl = new URL(import.meta.url);
    const candidate = path.join(path.dirname(selfUrl.pathname), "skill-ui-bridge.js");
    if (fs.existsSync(candidate)) return candidate;
  } catch (_) {}
  return null;
}

function resolveSkillsDir(api) {
  try {
    const workspaceDir =
      api.config?.agents?.defaults?.workspace ?? api.config?.workspace ?? null;
    if (workspaceDir) return path.join(workspaceDir, "skills");
  } catch (_) {}
  return null;
}

function resolveIndexHtmlPath() {
  const candidates = [
    "/usr/local/lib/node_modules/openclaw/dist/control-ui/index.html",
    "/usr/local/lib/.nvm/versions/node/v22.17.0/lib/node_modules/openclaw/dist/control-ui/index.html",
  ];
  try {
    const req = createRequire(import.meta.url);
    const pkgMain = req.resolve("openclaw");
    const pkgDir = path.dirname(pkgMain);
    candidates.unshift(path.join(pkgDir, "control-ui", "index.html"));
    candidates.unshift(path.join(path.dirname(pkgDir), "control-ui", "index.html"));
  } catch (_) {}
  for (const c of candidates) {
    if (fs.existsSync(c)) return c;
  }
  return null;
}

{
  "id": "skill-ui-bridge",
  "name": "Skill UI Bridge",
  "description": "Injects skill-ui-bridge.js into control-ui at gateway startup. Enables HTML card rendering in OpenClaw webchat.",
  "version": "2.1.0",
  "configSchema": {}
}

(function () {
  'use strict';

  var DONE_ATTR   = 'data-sui-done';
  var DEBOUNCE_MS = 320;

  var allowedTags  = new Set();
  var allowedAttrs = new Set();
  var ready = false;

  // ── 白名单净化 ────────────────────────────────────────────────────────────

  function sanitize(html) {
    var doc = new DOMParser().parseFromString('<body>' + html + '</body>', 'text/html');
    cleanNode(doc.body);
    return doc.body.innerHTML;
  }

  function cleanNode(node) {
    var i = node.childNodes.length;
    while (i--) {
      var child = node.childNodes[i];
      if (child.nodeType === 3) continue;
      if (child.nodeType !== 1) { node.removeChild(child); continue; }
      var tag = child.tagName.toLowerCase();
      if (!allowedTags.has(tag)) {
        var frag = document.createDocumentFragment();
        while (child.firstChild) frag.appendChild(child.firstChild);
        node.replaceChild(frag, child);
        continue;
      }
      var attrs = Array.from(child.attributes);
      for (var a = 0; a < attrs.length; a++) {
        if (!allowedAttrs.has(attrs[a].name)) child.removeAttribute(attrs[a].name);
      }
      cleanNode(child);
    }
  }

  // ── 骨架屏 ────────────────────────────────────────────────────────────────

  var SKELETON_STYLE = [
    '@keyframes sui-shimmer {',
    '  0%   { background-position: -400px 0 }',
    '  100% { background-position:  400px 0 }',
    '}',
    '.sui-skeleton {',
    '  display: block;',
    '  background: #fff;',
    '  border-radius: 10px;',
    '  padding: 12px 14px;',
    '  box-shadow: 0 2px 12px rgba(0,0,0,0.07);',
    '  width: 320px;',
    '  box-sizing: border-box;',
    '  overflow: hidden;',
    '}',
    '.sui-skeleton .sui-line {',
    '  border-radius: 5px;',
    '  background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);',
    '  background-size: 800px 100%;',
    '  animation: sui-shimmer 1.4s infinite linear;',
    '}',
  ].join('\n');

  var styleInjected = false;
  function injectStyle() {
    if (styleInjected) return;
    styleInjected = true;
    var s = document.createElement('style');
    s.textContent = SKELETON_STYLE;
    document.head.appendChild(s);
  }

  function createSkeleton() {
    injectStyle();
    var el = document.createElement('div');
    el.className = 'sui-skeleton';
    el.innerHTML = [
      '<div class="sui-line" style="height:12px;width:45%;margin-bottom:12px"></div>',
      '<div class="sui-line" style="height:8px;width:92%;margin-bottom:7px"></div>',
      '<div class="sui-line" style="height:8px;width:78%;margin-bottom:7px"></div>',
      '<div class="sui-line" style="height:8px;width:60%;margin-bottom:14px"></div>',
      '<div style="display:flex;gap:8px">',
      '  <div class="sui-line" style="height:8px;flex:2;border-radius:5px"></div>',
      '  <div class="sui-line" style="height:8px;flex:1;border-radius:5px"></div>',
      '</div>',
    ].join('');
    return el;
  }

  // ── 找消息气泡容器 ────────────────────────────────────────────────────────

  function findBubble(chatText) {
    var el = chatText.parentElement;
    var steps = 0;
    while (el && steps < 6) {
      var display = window.getComputedStyle(el).display;
      if (display !== 'inline' && display !== 'inline-block' &&
          el.tagName !== 'HTML' && el.tagName !== 'BODY') {
        return el;
      }
      el = el.parentElement;
      steps++;
    }
    return chatText;
  }

  // ── 检测 & 渲染 ───────────────────────────────────────────────────────────

  var MARKER_RE = /<div\s[^>]*class=["']a2ui["']/;
  var timers        = typeof WeakMap !== 'undefined' ? new WeakMap() : null;
  var skeletons     = typeof WeakMap !== 'undefined' ? new WeakMap() : null; // chatText → skeletonEl

  function renderChatText(el) {
    if (el.getAttribute(DONE_ATTR)) return;

    // 移除骨架屏
    function removeSkeleton() {
      if (!skeletons) return;
      var sk = skeletons.get(el);
      if (sk && sk.parentNode) {
        sk.parentNode.style.display = '';
        sk.parentNode.style.minWidth = '';
        sk.parentNode.removeChild(sk);
      }
      skeletons.delete(el);
    }

    var text = (el.textContent || '').trim();
    if (!MARKER_RE.test(text)) {
      removeSkeleton();
      el.style.display = '';
      return;
    }

    // 完整性检查
    var openCount  = (text.match(/<div[\s>]/g) || []).length;
    var closeCount = (text.match(/<\/div>/g)   || []).length;
    if (closeCount < openCount) {
      scheduleRender(el);
      return;
    }

    el.setAttribute(DONE_ATTR, '1');
    removeSkeleton();

    var aIdx = text.search(MARKER_RE);
    if (aIdx < 0) { el.style.display = ''; return; }

    var wrapper = document.createElement('div');
    wrapper.setAttribute(DONE_ATTR, '1');
    wrapper.style.cssText = 'display:block;margin:4px 0;opacity:0;transition:opacity 0.18s ease';
    wrapper.innerHTML = sanitize(text.slice(aIdx));

    el.style.display = '';
    el.innerHTML = '';
    el.appendChild(wrapper);

    requestAnimationFrame(function () {
      requestAnimationFrame(function () { wrapper.style.opacity = '1'; });
    });
  }

  function scheduleRender(el) {
    if (!timers) { renderChatText(el); return; }

    // 第一次：隐藏 chat-text，在其直接父节点里插入骨架屏
    if (skeletons && !skeletons.get(el)) {
      el.style.display = 'none';

      var parent = el.parentNode;
      var sk = createSkeleton();
      // 插到直接父节点，撑开气泡
      if (parent) {
        parent.style.display = 'inline-block';
        parent.style.minWidth = '320px';
        parent.appendChild(sk);
      }
      skeletons.set(el, sk);
    }

    var old = timers.get(el);
    if (old) clearTimeout(old);

    var tid = setTimeout(function () {
      timers.delete(el);
      renderChatText(el);
    }, DEBOUNCE_MS);
    timers.set(el, tid);
  }

  function processChatText(el) {
    if (!ready) return;
    if (el.getAttribute(DONE_ATTR)) return;
    var text = (el.textContent || '').trim();
    if (!MARKER_RE.test(text)) return;
    scheduleRender(el);
  }

  function walkAdded(node) {
    if (node.nodeType !== 1) return;
    if (node.classList && node.classList.contains('chat-text')) {
      processChatText(node);
      return;
    }
    var els = node.querySelectorAll ? node.querySelectorAll('.chat-text') : [];
    for (var i = 0; i < els.length; i++) processChatText(els[i]);
  }

  function walkMutation(mut) {
    if (mut.type === 'childList') {
      for (var i = 0; i < mut.addedNodes.length; i++) walkAdded(mut.addedNodes[i]);
    }
    var el = mut.target;
    while (el && el.nodeType === 3) el = el.parentNode;
    while (el) {
      if (el.classList && el.classList.contains('chat-text')) {
        processChatText(el);
        break;
      }
      el = el.parentElement;
    }
  }

  // ── 启动 ─────────────────────────────────────────────────────────────────

  function getAuthHeader() {
    try {
      var hash = location.hash.replace(/^#/, '');
      var hp = new URLSearchParams(hash);
      var t = hp.get('token');
      if (t) return 'Bearer ' + t;
      var raw = localStorage.getItem('openclaw.device.auth.v1');
      if (raw) { var d = JSON.parse(raw); if (d && d.token) return 'Bearer ' + d.token; }
      raw = localStorage.getItem('openclaw.control.settings.v1');
      if (raw) { var s = JSON.parse(raw); if (s && s.token) return 'Bearer ' + s.token; }
    } catch (e) {}
    return null;
  }

  async function boot() {
    try {
      var m;
      if (window.__skillUiManifest) {
        m = window.__skillUiManifest;
      } else {
        var authHeader = getAuthHeader();
        var fetchOpts = authHeader ? { headers: { 'Authorization': authHeader } } : {};
        var r = await fetch('/plugins/skill-ui/manifest', fetchOpts);
        if (!r.ok) { console.warn('[skill-ui-bridge] manifest', r.status); return; }
        m = await r.json();
      }

      (m.skills || []).forEach(function (s) {
        var c = s.config || {};
        ((c.dompurify && c.dompurify.allowedTags)  || []).forEach(function (t) { allowedTags.add(t);  });
        ((c.dompurify && c.dompurify.allowedAttrs) || []).forEach(function (a) { allowedAttrs.add(a); });
      });

      ready = true;
      walkAdded(document.body || document.documentElement);

      new MutationObserver(function (mutations) {
        for (var i = 0; i < mutations.length; i++) walkMutation(mutations[i]);
      }).observe(document.body || document.documentElement, {
        childList: true,
        subtree: true,
        characterData: true,
      });

      console.log('[skill-ui-bridge] boot ok, tags:', allowedTags.size, 'attrs:', allowedAttrs.size);
    } catch (e) {
      console.warn('[skill-ui-bridge] boot failed', e);
    }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();

# A2UI 卡片模板库（v0.9）

基于 A2UI v0.9 规范。每个模板都是完整的 JSONL，可直接修改数据部分使用。
`<SURFACE_ID>` 替换为唯一 ID（如 `reply_1741491234567`）。

> **v0.9 关键规则：**
> - 所有行加 `"version":"v0.9"`
> - `createSurface` 放第一行（替代 v0.8 的 `beginRendering`）
> - 组件格式：`"component":"Text"` + 属性平铺
> - 字符串直接写，不用 `{"literalString":"..."}` 包裹
> - `children` 直接数组 `["id1","id2"]`
> - `Image` 属性用 `url`（不是 `src`）
> - `updateDataModel` 的 `value` 是普通 JSON 对象

---

## text-card

**适用：** 纯文本摘要、结论、说明段落。

```jsonl
{"version":"v0.9","createSurface":{"surfaceId":"<SURFACE_ID>","catalogId":"openclaw/basic/v1"}}
{"version":"v0.9","updateComponents":{"surfaceId":"<SURFACE_ID>","components":[{"id":"root","component":"Card","child":"col"},{"id":"col","component":"Column","children":["title_row","body_text"],"gap":8},{"id":"title_row","component":"Row","children":["icon","title"],"gap":8,"align":"center"},{"id":"icon","component":"Icon","name":"info"},{"id":"title","component":"Text","text":{"path":"/title"},"variant":"h3"},{"id":"body_text","component":"Text","text":{"path":"/body"},"variant":"body"}]}}
{"version":"v0.9","updateDataModel":{"surfaceId":"<SURFACE_ID>","path":"/","value":{"title":"标题","body":"这里是正文内容。"}}}
```

---

## image-card

**适用：** 单图展示，图片说明。

> ⚠️ `Image` 组件的图片 URL 属性是 `url`，不是 `src`。

```jsonl
{"version":"v0.9","createSurface":{"surfaceId":"<SURFACE_ID>","catalogId":"openclaw/basic/v1"}}
{"version":"v0.9","updateComponents":{"surfaceId":"<SURFACE_ID>","components":[{"id":"root","component":"Card","child":"col"},{"id":"col","component":"Column","children":["image","caption_row"],"gap":0},{"id":"image","component":"Image","url":{"path":"/imageUrl"},"fit":"cover","variant":"hero"},{"id":"caption_row","component":"Column","children":["cap_text"],"gap":0},{"id":"cap_text","component":"Text","text":{"path":"/caption"},"variant":"caption"}]}}
{"version":"v0.9","updateDataModel":{"surfaceId":"<SURFACE_ID>","path":"/","value":{"imageUrl":"https://example.com/photo.jpg","caption":"图片说明文字"}}}
```

**多图画廊版：**
```jsonl
{"version":"v0.9","createSurface":{"surfaceId":"<SURFACE_ID>","catalogId":"openclaw/basic/v1"}}
{"version":"v0.9","updateComponents":{"surfaceId":"<SURFACE_ID>","components":[{"id":"root","component":"Card","child":"col"},{"id":"col","component":"Column","children":["title","gallery"],"gap":8},{"id":"title","component":"Text","text":{"path":"/title"},"variant":"h3"},{"id":"gallery","component":"Row","children":{"componentId":"img_item","path":"/images"},"gap":8},{"id":"img_item","component":"Image","url":{"path":"/url"},"fit":"cover"}]}}
{"version":"v0.9","updateDataModel":{"surfaceId":"<SURFACE_ID>","path":"/","value":{"title":"图片集","images":[{"url":"https://example.com/1.jpg"},{"url":"https://example.com/2.jpg"}]}}}
```

---

## video-card

**适用：** 视频播放（使用 OpenClaw Video 扩展组件）。

```jsonl
{"version":"v0.9","createSurface":{"surfaceId":"<SURFACE_ID>","catalogId":"openclaw/basic/v1"}}
{"version":"v0.9","updateComponents":{"surfaceId":"<SURFACE_ID>","components":[{"id":"root","component":"Card","child":"col"},{"id":"col","component":"Column","children":["player","info_col"],"gap":0},{"id":"player","component":"Video","src":{"path":"/videoSrc"},"poster":{"path":"/poster"},"controls":true,"autoplay":false},{"id":"info_col","component":"Column","children":["vid_title","vid_desc"],"gap":4},{"id":"vid_title","component":"Text","text":{"path":"/title"},"variant":"h3"},{"id":"vid_desc","component":"Text","text":{"path":"/desc"},"variant":"caption"}]}}
{"version":"v0.9","updateDataModel":{"surfaceId":"<SURFACE_ID>","path":"/","value":{"videoSrc":"https://example.com/video.mp4","poster":"https://example.com/thumb.jpg","title":"视频标题","desc":"视频描述"}}}
```

**YouTube 版：**
`videoSrc` 传入 `https://www.youtube.com/embed/<video_id>`

---

## list-card

**适用：** 要点列表、功能特性、注意事项。

